def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    colors = sorted({v for row in grid for v in row if v})
    tops = {}
    for c in colors:
        tops[c] = min(r for r in range(h) for x in range(w) if grid[r][x] == c)
    anchor = tops[8]
    for c in colors:
        shift = anchor - tops[c]
        for r in range(h):
            for x in range(w):
                if grid[r][x] == c:
                    nr = r + shift
                    if 0 <= nr < h:
                        out[nr][x] = c
    return out
